 private static void Refused(Action action){bool refused=false;try{action();}catch{refused=true;}TestRunner.True(refused,"Expected closed boundary refusal.");}
 private static void Shape(TestRunner t,Type type,string names){t.Run("authority DTO coverage "+type.Name,()=>TestRunner.True(type.GetProperties().Where(p=>p.CanRead&&p.CanWrite).Select(p=>p.Name).OrderBy(x=>x,StringComparer.Ordinal).SequenceEqual(names.Split(',').OrderBy(x=>x,StringComparer.Ordinal)),"A DTO property escaped explicit authority-key coverage."));}
 private static IEnumerable<Tuple<string,object,System.Reflection.PropertyInfo>> Scalars(object value,string prefix){foreach(var p in value.GetType().GetProperties().Where(p=>p.CanRead&&p.CanWrite)){var type=Nullable.GetUnderlyingType(p.PropertyType)??p.PropertyType;if(type==typeof(string)||type==typeof(int)||type==typeof(long)||type==typeof(bool))yield return Tuple.Create(prefix+"."+p.Name,value,p);}}
 private static IEnumerable<Tuple<string,object,System.Reflection.PropertyInfo>> RequestScalars(RuntimeRequest r){return Scalars(r,"request").Concat(Scalars(r.Fixture.Baseline,"baseline")).Concat(Scalars(r.Fixture.Working,"working")).Concat(Scalars(r.Fixture.WriteAuthorization,"writeAuthorization")).Concat(Scalars(r.QualificationSuite,"suite")).Concat(Scalars(r.PersistenceLoad,"load")).Concat(Scalars(r.CumulativeAcquisition,"selection")).Concat(Scalars(r.CumulativeAcquisition.Readiness,"readiness"));}
 private static object Mutated(Type type,object value){var actual=Nullable.GetUnderlyingType(type)??type;if(actual==typeof(string))return value==null?"changed":(string)value+"x";if(actual==typeof(bool))return value==null?true:!(bool)value;if(actual==typeof(int))return value==null?1:(int)value+1;if(actual==typeof(long))return value==null?1L:(long)value+1;throw new InvalidOperationException();}
